class Solution:
    def minCost(self, colors: str, neededTime: list[int]) -> int:
        ans = 0
        cur_max = neededTime[0]
        cur_sum = neededTime[0]
        for i in range(1, len(colors)):
            if colors[i] == colors[i - 1]:
                cur_sum += neededTime[i]
                cur_max = max(cur_max, neededTime[i])
            else:
                ans += cur_sum - cur_max
                cur_sum = neededTime[i]
                cur_max = neededTime[i]
        ans += cur_sum - cur_max
        return ans

#include <string>
#include <vector>
#include <algorithm>

class Solution {
public:
    int minCost(std::string colors, std::vector<int>& neededTime) {
        int ans = 0, n = colors.size();
        int curMax = neededTime[0], curSum = neededTime[0];
        for (int i = 1; i < n; ++i) {
            if (colors[i] == colors[i - 1]) {
                curSum += neededTime[i];
                curMax = std::max(curMax, neededTime[i]);
            } else {
                ans += curSum - curMax;
                curSum = neededTime[i];
                curMax = neededTime[i];
            }
        }
        ans += curSum - curMax;
        return ans;
    }
};

class Solution {
    public int minCost(String colors, int[] neededTime) {
        int ans = 0, n = colors.length();
        int curMax = neededTime[0], curSum = neededTime[0];
        for (int i = 1; i < n; i++) {
            if (colors.charAt(i) == colors.charAt(i - 1)) {
                curSum += neededTime[i];
                curMax = Math.max(curMax, neededTime[i]);
            } else {
                ans += curSum - curMax;
                curSum = neededTime[i];
                curMax = neededTime[i];
            }
        }
        ans += curSum - curMax;
        return ans;
    }
}

